inline int rectIds[3]{-1,-1,-1};
inline ImVec2 uv0[3]{},uv1[3]{};
inline void Register(ImFontAtlas& atlas) {
    const int widths[3]{donWidth,zuzaWidth,shuWidth},heights[3]{donHeight,zuzaHeight,shuHeight};
    for(int i=0;i<3;++i) if(rectIds[i]<0) rectIds[i]=atlas.AddCustomRectRegular(widths[i],heights[i]);
}
inline void Build(ImFontAtlas& atlas) {
    unsigned char* pixels=nullptr;int width=0,height=0;atlas.GetTexDataAsRGBA32(&pixels,&width,&height);
    const unsigned char* words[3]{donRle,zuzaRle,shuRle};
    const std::size_t sizes[3]{sizeof(donRle),sizeof(zuzaRle),sizeof(shuRle)};
    for(int i=0;i<3;++i) {
        auto* rect=atlas.GetCustomRectByIndex(rectIds[i]);if(!rect->IsPacked())continue;
        unsigned x=rect->X,y=rect->Y;const unsigned char* at=words[i];
        for(std::size_t p=0;p<sizes[i];p+=5) for(unsigned n=0;n<at[p];++n) {
            unsigned char* out=pixels+(y*width+x)*4;
            out[0]=at[p+1];out[1]=at[p+2];out[2]=at[p+3];out[3]=at[p+4];
            if(++x>=rect->X+rect->Width){x=rect->X;++y;}
        }
        atlas.CalcCustomRectUV(rect,&uv0[i],&uv1[i]);
    }
}
